import re, html
BASE = "https://col.guamcourts.gov"
INDEX = BASE + "/legal-publications/guam-code-annotated"
SEC = re.compile(r"^§\s*(\d+[A-Za-z]{0,2}\d*(?:\.\d+[A-Za-z]?)*)\.\s*(.*)$")
STRUCT = re.compile(r"^(ARTICLE|PART|SUBARTICLE|DIVISION|CHAPTER|SUBCHAPTER|SUBPART)\s+[0-9IVXLA-Z]+\b")
ANNOT = re.compile(r"^(COMPILER[’']?S?\s+COMMENTS?|COMMENTS?|NOTES?|\d{4}\s+NOTES?|COURT\s+DECISIONS|CROSS[- ]REFERENCES?|LAW\s+REVIEW\S*|EDITOR[’']?S?\s+NOTES?)\s*:")
LABEL = re.compile(r"^[A-Z][A-Z0-9’'\- ]{2,40}:")
FOOT = re.compile(r"^COL\s*[\d/\-]+$")

def chapters():
    kind, page = fetch(INDEX)
    title = None
    for m in re.finditer(r'href="([^"]+)"[^>]*>(.*?)</a>', page, re.S):
        href, label = m.group(1), " ".join(html.unescape(re.sub(r"<[^>]+>", " ", m.group(2))).split())
        if href.startswith("#faq"):
            t = re.match(r"Title (\d+)\s*:", label)
            title = t.group(1) if t else None
            continue
        if title and href.lower().endswith(".pdf") and re.match(r"(Chapter|Division|Article|Part)\b", label):
            yield title, label, (BASE + href if href.startswith("/") else href)

def lines_of(text):
    out = []
    for page in text.split("\n\n"):
        ls = [" ".join(l.split()) for l in page.split("\n")]
        head = [i for i, l in enumerate(ls[:6]) if l.isdigit()]
        if head and re.search(r"GCA", " ".join(ls[:head[0]])):
            ls = ls[head[0] + 1:]
        out += [l for l in ls if l and not FOOT.match(l)]
    return out

def parse(text):
    best, cur = {}, None
    for l in lines_of(text):
        m = SEC.match(l)
        if m:
            cur = {"id": m.group(1), "heading": m.group(2).strip(), "body": [], "stop": False, "src": False}
            best.setdefault(cur["id"], []).append(cur)
            continue
        if cur is None or cur["stop"]:
            continue
        if STRUCT.match(l) and l == l.upper() and len(l) < 120:
            cur["stop"] = True; continue
        if ANNOT.match(l) or (cur["src"] and LABEL.match(l) and not l.startswith("SOURCE")):
            cur["stop"] = True; continue
        if l.startswith("SOURCE:"):
            cur["src"] = True
        cur["body"].append(l)
    for sid, cands in best.items():
        c = max(cands, key=lambda c: sum(len(x) for x in c["body"]))
        body, head = c["body"], c["heading"]
        if body and head and not re.search(r"[.\])]$", head) and len(body[0]) < 150 and body[0].endswith(".") and not body[0].startswith("("):
            head = head + " " + body.pop(0)
        text = "\n".join(body).strip()
        if not text or re.search(r"\[\s*(Repealed|Reserved)", head + " " + text[:40], re.I) and len(text) < 400:
            continue
        yield sid, html.unescape(head).rstrip(" ."), html.unescape(text)

def sections():
    seen = set()
    for title, label, url in chapters():
        try:
            kind, text = fetch(url)
        except Exception as e:
            log(f"{url}: {e}"); continue
        if kind != "pdf":
            log(f"{url}: not a pdf ({kind})"); continue
        if len(text) >= 199000:
            log(f"TRUNCATED? {title} GCA {label}: {len(text)} chars from {url}")
        n = 0
        for sid, head, body in parse(text):
            if (title, sid) in seen:
                continue
            seen.add((title, sid)); n += 1
            yield {"id": sid, "heading": head, "text": body, "url": url, "vars": {"title": title}}
        if not n:
            log(f"no sections in {title} GCA {label} {url}")
